extern const unsigned char _binary_testrunnermodel_clp_start[];
extern const unsigned char _binary_testrunnermodel_clp_end[];
// _binary_*_size is an absolute symbol, not a pointer — cast its address to get the value
extern const uintptr_t _binary_testrunnermodel_clp_size;

