RetGetModelAsString get_testrunnermodel_as_string(){
	RetGetModelAsString ret = {
		.value = _binary_testrunnermodel_clp_start,
		.size = _binary_testrunnermodel_clp_end - _binary_testrunnermodel_clp_start,
	};
	return ret;
}

char* testrunner_input_script_as_rif_data(const char* script){
	int err;
	RIFIData* as_data;
	RIFIAtom* tmpatom;
	RIFITerm *op, *arg;
	RIFITermList *args;
	Mime2Rdf4C_SerializerConfig* ser;
	RIFIFormulas* formulas = RIFIFormulas_new();
	op = RIFITerm_new_iri("http://WhiteGobo.github.io/CIMR1SimpleOneshot/input#script");
	arg = RIFITerm_new_typedliteral(script, NULL);
	args = RIFITermList_append(NULL, arg);
	tmpatom = RIFIAtom_new(op, args);
	RIFIFormulas_add_atom(formulas, tmpatom);
	free_RIFIAtom(tmpatom);
	as_data = RIFIFormulas_to_RIFIData(formulas);

	ser = Mime2Rdf4C_get_serializer_from_ext("ttl");
	if(ser == NULL){
		free_RIFIData(as_data);
		return NULL;
	}
	err = RIFIData_send_as_rdf(as_data, (TripleHandler*) Mime2Rdf4C_add, ser);

	free_RIFIData(as_data);
	return Mime2Rdf4C_finish(ser);
}
